          <a v-if="viewMode === 'history'" class="finance-document-button" :href="documentUrl(selectedRow, 'receipt')" download>Official Receipt / 收据</a>
          <button :disabled="proofBusy" @click="chooseProof">{{ proofBusy ? $t('legacy.t_1e038f9b55ec') : selectedRow.proofDocumentId ? $t('legacy.t_7c9e4cb66071') : $t('legacy.t_0531fc112506') }}</button>
          <button @click="goToTenancy">{{ $t('legacy.t_bcdce2d6efbe') }}</button>
        </div>
        <div class="detail-section"><h4><span class="num">{{ $t('legacy.t_356a192b7913') }}</span>{{ $t('legacy.t_ce17f11e7211') }}</h4><div class="kv"><span>{{ $t('legacy.t_42c950a2ce7c') }}</span><b>{{ selectedRow.tenantName }}</b></div><div class="kv"><span>{{ $t('legacy.t_c6b9a8cfdb21') }}</span><b>{{ paymentMethodLabel(selectedRow.paymentMethod) }}</b></div><div class="kv"><span>{{ $t('legacy.t_9afa4ce0531c') }}</span><b>{{ selectedRow.transactionDate || '—' }}</b></div><div class="kv"><span>{{ $t('legacy.t_b35a920fa6f3') }}</span><b>{{ selectedRow.currency || 'MYR' }} {{ money(selectedRow.amount) }}</b></div></div>
        <div class="detail-section"><h4><span class="num">{{ $t('legacy.t_da4b9237bacc') }}</span>{{ $t('legacy.t_2e5d38a2bd27') }}</h4><div class="kv"><span>{{ $t('legacy.t_bd95f007d6d0') }}</span><b>{{ selectedRow.leaseNo }}</b></div><div class="kv"><span>{{ $t('legacy.t_a7ff541f4978') }}</span><b>{{ monthLabel(selectedRow.billingMonth) }}</b></div><div class="kv"><span>{{ $t('legacy.t_fdeda5befee2') }}</span><b>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow.invoiceAmount) }}</b></div><div class="kv"><span>{{ $t('legacy.t_109f4a1ff366') }}</span><b>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(selectedRow.invoicePaid) }}</b></div><div class="progress"><i :style="{ width: invoiceProgress + '%' }"></i></div></div>
        <div class="detail-section"><h4><span class="num">{{ $t('legacy.t_77de68daecd8') }}</span>{{ $t('legacy.t_8048e4b28ff2') }}</h4><div class="kv"><span>{{ $t('legacy.t_b7aeb7e21fa3') }}</span><b>{{ selectedRow.proofName || $t('legacy.t_3c5b845dce11') }}</b></div><div class="kv"><span>{{ $t('legacy.t_2ad8b0b96fec') }}</span><b>{{ fileSize(selectedRow.proofSize) }}</b></div><div class="kv"><span>{{ $t('legacy.t_94007fdd6e4e') }}</span><b>{{ syncLabel(selectedRow.syncStatus) }}</b></div><div class="kv"><span>{{ $t('legacy.t_f3f199f6441e') }}</span><b>{{ formatDateTime(selectedRow.submittedAt) }}</b></div></div>
