      <div v-else class="admin-owner-empty">{{ $t('legacy.t_16c5e3b671a3') }}</div>
    </aside>

    <dialog ref="proofDialog" class="modal admin-finance-proof-dialog"><div class="modal-head"><div><h3>{{ $t('legacy.t_08ca85f55e3c') }}</h3><small>{{ selectedRow?.proofName || selectedRow?.transactionNo }}</small></div><button type="button" class="icon-close" @click="closeProof">×</button></div><div class="finance-proof-viewer"><div v-if="proofLoading" class="admin-owner-state">{{ $t('legacy.t_e526ed184e85') }}</div><img v-else-if="proofUrl && selectedRow?.proofMimeType?.startsWith('image/')" :src="proofUrl" :alt="$t('legacy.t_08ca85f55e3c')"><iframe v-else-if="proofUrl && selectedRow?.proofMimeType === 'application/pdf'" :src="proofUrl" :title="$t('legacy.t_b1c0f608af9c')"></iframe><div v-else class="admin-owner-state">{{ proofError || $t('legacy.t_410b7e2a33ff') }}</div></div><menu><button @click="closeProof">{{ $t('legacy.t_ddc05404b0d6') }}</button><button class="primary-btn" :disabled="!selectedRow?.proofDocumentId" @click="downloadProof">{{ $t('legacy.t_fb332e3c9ee6') }}</button></menu></dialog>
  </section>
</template>

<script>
import { downloadAdminFinanceDocuments, fetchAdminRentFinanceProjects, fetchAdminRentFinanceReviews, fetchAdminRentProof, getAdminFinanceDocumentUrl, getAdminRentReceiptUrl, uploadAdminRentProof } from '../services/propertyApi';

export default {
  inject: ['page'],
  data() { return { rows: [], selectedId: null, pageNumber: 1, pageSize: 10, totalRows: 0, totalPages: 1, loading: false, errorMessage: '', requestSerial: 0, proofBusy: false, receiptBusy: false, historyMonth: '', tenantFilter: '', unitFilter: '', proofLoading: false, proofError: '', proofUrl: '' }; },
  computed: {
    selectedRow() { return this.rows.find(row => row.id === this.selectedId) || null; },
    visiblePages() { const start = Math.max(1, Math.min(this.pageNumber - 2, this.totalPages - 4)); return Array.from({ length: Math.min(5, this.totalPages) }, (_, i) => start + i); },
    invoiceProgress() { return !Number(this.selectedRow?.invoiceAmount) ? 0 : Math.min(100, Math.round(Number(this.selectedRow.invoicePaid || 0) / Number(this.selectedRow.invoiceAmount) * 100)); },
    refreshNonce() { return this.page.adminFinanceRefreshNonce; },
    proofUploadNonce() { return this.page.adminRentProofUploadNonce; }
  },
  watch: {
    'page.moduleSearch'() { this.resetLoad(); }, 'page.globalSearch'() { this.resetLoad(); }, 'page.projectFilter'() { this.resetLoad(); }, 'page.statusFilter'() { this.resetLoad(); }, 'page.dateStart'() { this.resetLoad(); }, 'page.dateEnd'() { this.resetLoad(); }, historyMonth() { this.resetLoad(); }, tenantFilter() { this.resetLoad(); }, unitFilter() { this.resetLoad(); },
    pageSize() { this.pageNumber = 1; this.loadData(); }, refreshNonce(value, previous) { if (value > previous) this.loadData(); }, proofUploadNonce(value, previous) { if (value > previous) this.chooseProof(); }, rows: { deep: true, handler(rows) { if (!rows.some(row => row.id === this.selectedId)) this.selectedId = null; } }
  },
  mounted() { this.loadData(); }, beforeUnmount() { this.revokeProofUrl(); },
  methods: {
    async loadData() { const serial = ++this.requestSerial; const preferredId = this.selectedId; this.loading = true; this.errorMessage = ''; try { const [response, projects] = await Promise.all([fetchAdminRentFinanceReviews({ page: this.pageNumber, pageSize: this.pageSize, keyword: this.page.globalSearch || this.page.moduleSearch || '', projectName: String(this.page.projectFilter || '').includes('全部') ? '' : this.page.projectFilter, status: this.statusParam(this.page.statusFilter) || 'history', startDate: this.page.dateStart, endDate: this.page.dateEnd, billingMonth: this.historyMonth ? `${this.historyMonth}-01` : '', tenantName: this.tenantFilter, unitNo: this.unitFilter }), fetchAdminRentFinanceProjects()]); if (serial !== this.requestSerial) return; this.rows = response.rows || []; this.totalRows = response.page?.totalRows || 0; this.totalPages = response.page?.totalPages || 1; this.pageNumber = response.page?.page || 1; this.selectedId = this.rows.some(row => row.id === preferredId) ? preferredId : null; this.page.adminFinanceProjects = projects || []; this.page.adminFinanceMetrics = this.metrics(response.summary || {}); } catch (e) { if (serial !== this.requestSerial) return; this.rows = []; this.errorMessage = e.message || 'API request failed'; this.page.adminFinanceMetrics = null; } finally { if (serial === this.requestSerial) this.loading = false; } },
    metrics(s) { return [{ label: '租金收款記錄', value: `${Number(s.totalCount || 0)} 筆`, delta: `RM ${this.money(s.totalAmount)}`, trend: 'up' }, { label: '已上傳憑證', value: `${Number(s.withProofCount || 0)} 筆`, delta: '線下審批憑證', trend: 'up' }, { label: '缺少憑證', value: `${Number(s.missingProofCount || 0)} 筆`, delta: '需要補上文件', trend: Number(s.missingProofCount) ? 'down' : 'up' }, { label: '待同步 SQL', value: `${Number(s.pendingSyncCount || 0)} 筆`, delta: '會計同步狀態', trend: Number(s.pendingSyncCount) ? 'down' : 'up' }, { label: '本月收款金額', value: `RM ${this.money(s.monthAmount)}`, delta: '按收款日期統計', trend: 'up' }]; },
    resetLoad() { this.pageNumber = 1; this.loadData(); }, clearHistoryFilters() { this.historyMonth = ''; this.tenantFilter = ''; this.unitFilter = ''; }, goPage(n) { if (n >= 1 && n <= this.totalPages && n !== this.pageNumber) { this.pageNumber = n; this.loadData(); } }, selectRow(row) { this.selectedId = row.id; }, documentUrl(row, type) { return row?.id ? getAdminFinanceDocumentUrl(row.id, type) : '#'; }, async batchDownload(type) { const ids = this.rows.map(row => row.id).filter(Boolean); if (!ids.length) { this.page.showToast('当前没有可下载的历史记录'); return; } try { const result = await downloadAdminFinanceDocuments(ids, type); this.saveBlob(result.blob, result.filename); this.page.showToast(`已生成 ${ids.length} 份${type === 'invoice' ? '发票' : '收据'}`); } catch (error) { this.page.showToast(error.message || '批量下载失败'); } },
    proofAction(row) { this.selectRow(row); this.$nextTick(() => row.proofDocumentId ? this.openProof() : this.chooseProof()); }, chooseProof() { if (!this.selectedRow || this.proofBusy) return; this.$refs.proofInput.value = ''; this.$refs.proofInput.click(); },
    async uploadSelectedProof(event) { const file = event.target.files?.[0]; if (!file) return; if (!this.validProof(file)) { event.target.value = ''; return; } const replacing = Boolean(this.selectedRow.proofDocumentId); this.proofBusy = true; try { await uploadAdminRentProof(this.selectedRow.id, file); await this.loadData(); this.page.showToast(replacing ? '租金憑證已更換' : '租金憑證已補上'); } catch (e) { this.page.showToast(e.message || '租金憑證上傳失敗'); } finally { this.proofBusy = false; event.target.value = ''; } }, validProof(file) { if (!['application/pdf', 'image/jpeg', 'image/png'].includes(file.type) || file.size > 10 * 1024 * 1024) { this.page.showToast('只支援 10MB 以內的 PDF、JPG 或 PNG 憑證'); return false; } return true; },
     async openProof() { if (!this.selectedRow?.proofDocumentId) return; this.revokeProofUrl(); this.proofLoading = true; this.proofError = ''; this.$refs.proofDialog?.showModal(); try { const result = await fetchAdminRentProof(this.selectedRow.proofDocumentId); this.proofUrl = URL.createObjectURL(result.blob); } catch (e) { this.proofError = e.message || '租金付款憑證載入失敗'; } finally { this.proofLoading = false; } }, closeProof() { this.$refs.proofDialog?.close(); this.revokeProofUrl(); }, revokeProofUrl() { if (this.proofUrl) URL.revokeObjectURL(this.proofUrl); this.proofUrl = ''; }, async downloadProof() { try { const result = await fetchAdminRentProof(this.selectedRow.proofDocumentId, true); this.saveBlob(result.blob, this.selectedRow.proofName || `rent-proof-${this.selectedRow.id}`); } catch (e) { this.page.showToast(e.message || '租金付款憑證下載失敗'); } }, async downloadReceipt(row = this.selectedRow) { if (!row?.id || this.receiptBusy) return; this.receiptBusy = true; try { window.location.assign(getAdminRentReceiptUrl(row.id)); this.page.showToast('租金收據下載已開始'); } catch (e) { this.page.showToast(e.message || '租金收據下載失敗'); } finally { this.receiptBusy = false; } }, saveBlob(blob, fileName) { const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = fileName; link.style.display = 'none'; document.body.appendChild(link); link.click(); window.setTimeout(() => { link.remove(); URL.revokeObjectURL(url); }, 1000); },
    goToTenancy() { const keyword = this.selectedRow?.tenantName || this.selectedRow?.unitNo || ''; this.page.selectModule('adminTenants'); this.$nextTick(() => { this.page.globalSearch = keyword; }); }, receiptUrl(row) { return row?.id ? getAdminRentReceiptUrl(row.id) : '#'; }, statusParam(v) { return ({ '已確認': 'confirmed', '已退回': 'rejected', '待同步': 'sync_pending', '同步失敗': 'sync_failed' })[v] || ''; }, confirmationLabel(v) { return ({ confirmed: '已確認', rejected: '已退回' })[v] || '已完成'; }, confirmationClass(v) { return v === 'rejected' ? 'red' : 'green'; }, syncLabel(v) { return ({ not_synced: '未同步', pending: '待同步', synced: '已同步', failed: '同步失敗' })[v] || '未同步'; }, syncClass(v) { return v === 'synced' ? 'green' : v === 'failed' ? 'red' : 'orange'; }, paymentMethodLabel(v) { return ({ bank_transfer: '銀行轉帳', online_transfer: '網上轉帳', cheque: '支票', cash: '現金', online_banking: '網上銀行' })[v] || v || '—'; }, monthLabel(v) { return v ? String(v).slice(0, 7) : '—'; }, formatDateTime(v) { return v ? String(v).replace('T', ' ').slice(0, 19) : '—'; }, fileSize(v) { if (!v) return '—'; return v >= 1024 * 1024 ? `${(v / 1024 / 1024).toFixed(1)} MB` : `${Math.ceil(v / 1024)} KB`; }, money(v) { return Number(v || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
}
};
</script>

