e}.finance-proof-link.receipt-link:hover{background:#f2f7fc}.rent-history-filters{display:flex;gap:10px;align-items:end;padding:12px 0}.rent-history-filters label{display:grid;gap:4px;color:#52657a;font-size:12px}.rent-history-filters input{border:1px solid #cdd8e4;border-radius:6px;padding:8px 9px}.rent-history-filters>button{border:1px solid #cdd8e4;background:#fff;border-radius:6px;padding:8px 12px}
</style>
<style scoped>
